# goal_ack.py

def acknowledge_goal(goal, user_id: str):
    if goal.created_by != user_id:
        raise PermissionError("Only the requester can acknowledge this goal")

    if goal.state != "awaiting_ack":
        raise ValueError("Goal is not awaiting acknowledgement")

    goal.report_acknowledged = True
    goal.acknowledged_at = now()
    goal.state = "complete"

    save_goal(goal)

    return goal

# heartbeat.py

def find_unreported_verified_goals(goal_store):
    return goal_store.query(
        state="verified",
        verified_at__not_null=True,
        reported_at=None
    )


def repair_unreported_goals(goal_store, reporter):
    stale_goals = find_unreported_verified_goals(goal_store)

    for goal in stale_goals:
        finalize_verified_goal(goal, reporter)

def assert_goal_integrity(goal):
    if goal.state == "complete":
        assert goal.verified_at is not None
        assert goal.reported_at is not None
        assert goal.report_acknowledged is True

# goal_states.py

from enum import Enum


class GoalState(str, Enum):
    PENDING = "pending"
    EXECUTING = "executing"
    VERIFYING = "verifying"
    VERIFIED = "verified"
    REPORTING = "reporting"
    AWAITING_ACK = "awaiting_ack"
    COMPLETE = "complete"
    FAILED = "failed"

# goal_completion.py

def can_mark_complete(goal) -> bool:
    return (
        goal.state == "awaiting_ack"
        and goal.verified_at is not None
        and goal.reported_at is not None
        and goal.report_acknowledged is True
    )

# goal_engine.py

def finalize_verified_goal(goal, reporter):
    if not goal.verified_at:
        raise ValueError("Goal cannot finalize before verification")

    goal.state = "reporting"

    report = build_completion_report(goal)

    reporter.send(
        user_id=goal.created_by,
        message=report
    )

    goal.reported_at = now()
    goal.state = "awaiting_ack"

    save_goal(goal)

    return goal

def build_completion_report(goal) -> str:
    return f"""
Goal complete pending acknowledgement.

Goal: {goal.title}
Goal ID: {goal.id}
Status: verified

Summary:
{goal.summary or "No summary provided."}

Files changed:
{format_list(goal.files_changed)}

Tests run:
{format_list(goal.tests_run)}

Result:
{goal.result or "No result recorded."}

Next step:
Please acknowledge, reject, or request revision.
""".strip()


def format_list(items):
    if not items:
        return "- None"
    return "\n".join(f"- {item}" for item in items)
